    function run(address unrelated, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(unrelated != address(this));
        require(address(this).balance >= amount);
        uint before_ = c.getBalance(unrelated); if (__ESBMC_reverted()) return;
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
