// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address unrelated, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(unrelated != address(this));
        vm.assume(address(this).balance >= amount);
        uint256 before_;
        try c.getBalance(unrelated) returns (uint256 __r) { before_ = __r; } catch { return; }
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 afterVal;
        try c.getBalance(unrelated) returns (uint256 __r) { afterVal = __r; } catch { return; }
        assertTrue(before_ == 0 && afterVal == 0 && c.getBalance(address(this)) == amount);
    }

    function testFuzz_run(address unrelated, uint256 amount) public {
        vm.assume(unrelated.code.length == 0 && uint160(unrelated) > 0xffff && unrelated != address(this) && unrelated != address(c) && unrelated != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && unrelated != 0x000000000000000000636F6e736F6c652e6c6f67 && unrelated != 0x4e59b44847b379578588920cA78FbF26c0B4956C && unrelated != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(unrelated, amount);
    }

    receive() external payable {}
}
